```
function clampAngle(value, min, max) {
  if (!finite) return value;
  const TWO_PI = 2π;
  const EPS = 1e-9;
  const span = ((max - min) % TWO_PI + TWO_PI) % TWO_PI;
  if (span >= TWO_PI - EPS) return value; // full
  if (span <= EPS) return normalizeAngle(min); // point
  const t = ((value - min) % TWO_PI + TWO_PI) % TWO_PI;
  let clampedT;
  if (t <= span + EPS) clampedT = Math.min(Math.max(t, 0), span);
  else {
    const distToMax = t - span;
    const distToMin = TWO_PI - t;
    clampedT = distToMax <= distToMin ? span : 0;
  }
  return normalizeAngle(min + clampedT);
}
