```
import type { GeospatialCamera, GeospatialLimits } from "@babylonjs/lite";

type ModeLimitsState = {
  limits: GeospatialLimits;
  radius: number;
  yaw: number;
  radiusGet?: () => number;
  radiusSet?: (value: number) => void;
  yawGet?: () => number;
  yawSet?: (value: number) => void;
  setOrientation?: (yaw: number, pitch: number, radius: number, center: unknown) => void;
  installed: boolean;
  applying: boolean;
};

const states = new WeakMap<GeospatialCamera, ModeLimitsState>();

const TWO_PI = Math.PI * 2;
const EPS = 1e-9;

function clampRadius(limits: GeospatialLimits, radius: number): number {
  if (!Number.isFinite(radius)) return radius;
  let min = limits.radiusMin;
  let max = limits.radiusMax;
  if (!Number.isFinite(min) || !Number.isFinite(max)) return radius;
  if (min > max) {
    const t = min;
    min = max;
    max = t;
  }
  return Math.min(Math.max(radius, min), max);
}

function normalize01(angle: number): number {
  const n = angle % TWO_PI;
  return n < 0 ? n + TWO_PI : n;
}

function clampYaw(limits: GeospatialLimits, yaw: number): number {
  if (!Number.isFinite(yaw)) return yaw;
  const min = limits.yawMin;
  const max = limits.yawMax;
  if (!Number.isFinite(min) || !Number.isFinite(max)) return yaw;

  // A range covering a full circle imposes no heading limit.
  if (max - min >= TWO_PI - EPS || min - max >= TWO_PI - EPS) {
    return yaw;
  }

  if (min <= max) {
    return Math.min(Math.max(yaw, min), max);
  }

  // Wrap-around range, e.g. 350deg..10deg. Use the normalized [0, 2π) space.
  const minN = normalize01(min);
  const maxN = normalize01(max);
  const y = normalize01(yaw);

  if (minN > maxN) {
    if (y >= minN || y <= maxN) {
      return y;
    }
    const distanceToMax = (y - maxN + TWO_PI) % TWO_PI;
    const distanceToMin = (minN - y + TWO_PI) % TWO_PI;
    return distanceToMax <= distanceToMin ? maxN : minN;
  }

  // min > max but the normalized bounds do not wrap; fall back to a plain clamp.
  return Math.min(Math.max(yaw, max), min);
}

function findDescriptor(target: object, key: string): PropertyDescriptor | undefined {
  let current: object | null = target;
  while (current) {
    const descriptor = Object.getOwnPropertyDescriptor(current, key);
    if (descriptor) return descriptor;
    current = Object.getPrototypeOf(current);
  }
  return undefined;
}

function getState(camera: GeospatialCamera): ModeLimitsState {
  let state = states.get(camera);
